package pl.zagranietyper;
import org.junit.jupiter.api.Test;import pl.zagranietyper.repository.FootballSettlementRepository;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.jupiter.api.Assertions.*;
class FootballPeriodStatisticsReviewedSnapshotTest {@Test void immutableBoundaryIsExact(){assertEquals(Set.of(1862L,10717L),FootballPeriodStatisticsReviewedSnapshot.APPROVED_IDS);assertEquals("3a87edce7a29e883f9cd4da7b50240f717c939c8b48967de8b68bd23022b597b",FootballPeriodStatisticsReviewedSnapshot.EXPECTED_SHA256);}@Test void failedGateNeverWrites(){var n=new AtomicInteger();assertThrows(IllegalStateException.class,()->FootballPeriodStatisticsCoverageDryRunMain.applyIfRequested(gate(false),List.of(),u->{n.incrementAndGet();return ok();}));assertEquals(0,n.get());}@Test void passingGateDelegates(){var n=new AtomicInteger();assertEquals(2,FootballPeriodStatisticsCoverageDryRunMain.applyIfRequested(gate(true),List.of(),u->{n.incrementAndGet();return ok();}).updatedLegs());assertEquals(1,n.get());}private static FootballPeriodStatisticsReviewedSnapshot.Gate gate(boolean p){return new FootballPeriodStatisticsReviewedSnapshot.Gate(2,1,1,0,"hash",Set.of(),Set.of(),p,p,p,p);}private static FootballSettlementRepository.ApplyResult ok(){return new FootballSettlementRepository.ApplyResult(2,0,1,1,0,2,1,1,0,0,0);}}
